insert into public.products (slug, name, description, care_instructions, shipping_info, returns_info, base_price, cost_price, product_kind, is_bestseller, materials, created_at) values ('imara-signet-ring', 'Imara Signet Ring', 'A weighted signet with a hand-brushed face, cast in small batches. Imara — meaning ''strong'' — anchors the hand with quiet permanence.', 'Keep dry, store flat in the provided pouch, polish with a soft cloth only.', 'Made to order — ships within 5–7 working days across Kenya, 10–14 days internationally.', 'Exchanges accepted within 14 days for unworn pieces in original packaging.', 6800, 3740, 'INDIVIDUAL_PIECE', true, array['18k gold vermeil over recycled brass', 'Hand-brushed finish'], '2026-06-01'::timestamptz) on conflict (slug) do nothing;
